parameters.functionCode:
// Extract and validate voice query
const body = $input.item.json.body;

const transcript = body.transcript || body.query || '';
const language = body.language || 'ta-IN';
const callId = body.call_id || body.callId;
const entities = body.extracted_entities || body.entities || {};

if (!transcript) {
  throw new Error('Missing transcript in voice query');
}

// Determine query type
const queryType = body.query_type || determineQueryType(transcript, entities);

function determineQueryType(text, ents) {
  const lower = text.toLowerCase();

  if (lower.includes('scheme') || lower.includes('pension') || lower.includes('योजना') || lower.includes('திட்டம்')) {
    return 'scheme_search';
  }

  if (Object.keys(ents).length >= 3) {
    return 'profile_creation';
  }

  return 'general_query';
}

return {
  json: {
    transcript,
    language,
    call_id: callId,
    entities,
    query_type: queryType,
    timestamp: new Date().toISOString()
  }
};

// Merge results from web scraper and RAG
const webResults = $('search-schemes').item.json.schemes || [];
let ragResults = [];

try {
  ragResults = $('rag-search').item.json.schemes || [];
} catch (e) {
  // RAG failed, use only web results
}

// Deduplicate by scheme_id
const seen = new Set();
const merged = [];

for (const scheme of [...webResults, ...ragResults]) {
  if (!seen.has(scheme.scheme_id || scheme.id)) {
    seen.add(scheme.scheme_id || scheme.id);
    merged.push(scheme);
  }
}

return {
  json: {
    schemes: merged.slice(0, 5),
    source_count: {
      web: webResults.length,
      rag: ragResults.length,
      merged: merged.length
    }
  }
};

// Format response for voice output
const originalLang = $('validate-voice-input').item.json.language;
const schemes = $json.eligible_schemes || $json.schemes || [];

let responseText = '';

if (schemes.length === 0) {
  responseText = 'I could not find any matching schemes for your query. Please try rephrasing or contact a Community Health Worker for assistance.';
} else {
  // Create summary
  const schemeNames = schemes.slice(0, 3).map(s => s.title || s.name).join(', ');
  responseText = `I found ${schemes.length} schemes that may help you. The top matches are: ${schemeNames}.`;

  // Add eligibility info if available
  if ($json.eligible_count) {
    responseText += ` You appear to be eligible for ${$json.eligible_count} of these schemes based on your profile.`;
  }

  responseText += ' Would you like more details about any specific scheme?';
}

return {
  json: {
    response_text: responseText,
    schemes: schemes,
    language: originalLang,
    requires_translation: originalLang !== 'en',
    call_id: $('validate-voice-input').item.json.call_id
  }
};

