// Handle profile creation queries
const entities = $('validate-voice-input').item.json.entities;
const language = $('validate-voice-input').item.json.language;

// Check if we have enough data to create profile
const requiredFields = ['age', 'marital_status', 'monthly_income'];
const hasRequiredData = requiredFields.every(field => entities[field]);

if (!hasRequiredData) {
  return {
    json: {
      status: 'incomplete',
      message: 'I need more information to help you. Can you tell me your age, marital status, and monthly household income?',
      missing_fields: requiredFields.filter(f => !entities[f]),
      language
    }
  };
}

// Create household profile
const profile = {
  household_id_hash: `voice_${Date.now()}`,
  profile_json: entities,
  location_district: entities.location || 'Unknown',
  consent_ledger_json: {
    voice_consent: true,
    timestamp: new Date().toISOString()
  },
  sync_status: 'pending'
};

return {
  json: {
    status: 'complete',
    profile,
    message: 'Thank you for providing your information. I will now check which schemes you are eligible for.',
    language
  }
};
